) ?>"></label><label>Per contact<input name="per_customer_limit" type="number" min="1" max="25" value="<?= (int)($editReward['per_customer_limit']??1) ?>"></label><label>Status<select name="status"><option value="active"<?= ($editReward['status']??'active')==='active'?' selected':'' ?>>Active</option><option value="inactive"<?= ($editReward['status']??'')==='inactive'?' selected':'' ?>>Inactive</option></select></label></div><label>Description<textarea name="description"><?= e((string)($editReward['description']??'')) ?></textarea></label><button class="cr-btn">Save Reward Product</button></form></section>
